import { useState } from "react";
import type { ReactNode } from "react";
import { Modal, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface ContextMenuItem {
  id: string;
  label: string;
  icon?: ReactNode;
  onSelect?: () => void;
  disabled?: boolean;
  destructive?: boolean;
  checked?: boolean;
}

export interface ContextMenuProps {
  children: ReactNode;
  items: ContextMenuItem[];
  label?: string;
  /** Extend the inner, named parts of the menu: content, item or itemText. The React Native counterpart of `classNames`. */
  styles?: {
    content?: StyleProp<ViewStyle>;
    item?: StyleProp<ViewStyle>;
    itemText?: StyleProp<TextStyle>;
  };
}

/** A long press on the content opens the menu as a sheet from the bottom edge. */
export function ContextMenu({ children, items, label = "Context menu", styles: parts }: ContextMenuProps) {
  const tokens = useTokens();
  const [open, setOpen] = useState(false);

  return (
    <>
      <Pressable accessibilityHint="Long press for more actions" onLongPress={() => setOpen(true)} delayLongPress={380}>
        {children}
      </Pressable>
      <Modal transparent animationType="slide" visible={open} onRequestClose={() => setOpen(false)} statusBarTranslucent>
        <Pressable accessibilityLabel="Close menu" onPress={() => setOpen(false)} style={local.overlay}>
          <View accessibilityRole="menu" accessibilityLabel={label} style={[local.content, { borderColor: tokens.border, backgroundColor: tokens.surface }, parts?.content]}>
            {items.map((item) => (
              <Pressable
                key={item.id}
                accessibilityRole="menuitem"
                accessibilityState={{ disabled: item.disabled, checked: item.checked }}
                disabled={item.disabled}
                onPress={() => {
                  setOpen(false);
                  item.onSelect?.();
                }}
                style={({ pressed }) => [local.item, { backgroundColor: pressed ? tokens.surfaceMuted : "transparent", opacity: item.disabled ? 0.45 : 1 }, parts?.item]}
              >
                {item.icon}
                <Text style={[{ flex: 1, color: item.destructive ? tokens.danger : tokens.foreground, fontSize: metrics.text.sm }, parts?.itemText]}>{item.label}</Text>
                {item.checked ? <Text style={{ color: tokens.foreground }}>✓</Text> : null}
              </Pressable>
            ))}
          </View>
        </Pressable>
      </Modal>
    </>
  );
}

const local = StyleSheet.create({
  overlay: { flex: 1, justifyContent: "flex-end", padding: metrics.space[3], backgroundColor: "rgba(10, 10, 10, 0.4)" },
  content: { borderWidth: 1, borderRadius: 26, padding: 6 },
  item: { flexDirection: "row", alignItems: "center", gap: metrics.space[3], minHeight: metrics.controlHeight.md, paddingHorizontal: metrics.space[4], borderRadius: metrics.radiusControl - 4 },
});

export default ContextMenu;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
